def test_singleton(run, x):
    p = list(map(int, x.split()))
    n, I = p[:2]
    a = p[2:]
    vals = sorted(set(a))
    best = n
    for l in vals:
        for r in vals:
            if l <= r:
                b = [l if z < l else r if z > r else z for z in a]
                if n * (len(set(b)) - 1).bit_length() <= 8 * I:
                    best = min(best, sum(z != q for z, q in zip(a, b)))
    s = run(x).strip()
    assert s.isdigit()
    assert int(s) == best

