def test_exhaustive_digit_sum_01(run, x):
    n, s = map(int, x.split())
    expected = -1
    for b in range(2, n + 2):
        q = n
        total = 0
        while q:
            total += q % b
            q //= b
        if total == s:
            expected = b
            break
    tokens = run(x).split()
    assert len(tokens) == 1
    try:
        actual = int(tokens[0])
    except ValueError:
        assert False
    assert actual == expected

