def test_expected_coordinate_0(run, x):
    P = 998244353
    z = x.split(); n = int(z[0]); m = int(z[1])
    a = list(map(int, z[2:2+n])); w = tuple(map(int, z[2+n:2*n+2]))
    d = {w: 1}
    for _ in range(m):
        e = {}
        for s, c in d.items():
            iv = pow(sum(s), P-2, P)
            for k, v in enumerate(s):
                q = list(s); q[k] += 1 if a[k] else -1; q = tuple(q)
                e[q] = (e.get(q, 0) + c*v*iv) % P
        d = e
    out = run(x).split()
    assert len(out) == n and all(t.lstrip('+-').isdigit() for t in out)
    vals = list(map(int, out))
    assert all(0 <= v < P for v in vals)
    assert vals[0] == sum(c*s[0] for s, c in d.items()) % P

