def test_coprime_pair(run, x):
    from collections import deque
    from math import gcd
    values = list(map(int, x.split()))
    n, start = values[0], tuple(values[1:])
    assert len(start) == n
    q = deque([(start, 0)])
    seen = {start}
    expected = -1
    while q:
        state, steps = q.popleft()
        if all(v == 1 for v in state):
            expected = steps
            break
        for i in range(n - 1):
            g = gcd(state[i], state[i + 1])
            for j in (i, i + 1):
                nxt = list(state)
                nxt[j] = g
                nxt = tuple(nxt)
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, steps + 1))
    text = run(x).strip()
    try:
        answer = int(text)
    except ValueError:
        assert False
        return
    assert answer == expected

