def test_minimum_root_contributions(run, x):
    s = x.strip()
    boundary = set()
    def walk(p, last, used):
        if p == len(s):
            boundary.update(used)
            return
        for q in (2, 3):
            t = s[p:p + q]
            if p + q <= len(s) and t != last:
                walk(p + q, t, used + (t,))
    walk(5, None, ())
    lines = run(x).strip().splitlines()
    assert lines and lines[0].isdigit()
    assert boundary <= set(lines[1:])

