    e = a[2 + 2 * k:]
    g = [[] for _ in range(n)]
    for i in range(0, len(e), 2):
        p, q = e[i] - 1, e[i + 1] - 1
        g[p].append(q); g[q].append(p)
    d = []
    for s in range(n):
        z = [-1] * n; z[s] = 0; q = [s]
        for p in q:
            for v in g[p]:
                if z[v] < 0: z[v] = z[p] + 1; q.append(v)
        d.append(z)
    def best(s):
        return 0 if not s else max(d[s[0]][v] + best(s[1:i] + s[i + 1:]) for i, v in enumerate(s[1:], 1))
    assert int(out.strip()) == best(u)

