def test_single_pair_separated(run, x):
    a = list(map(int, x.split()))
    n, k = a[0], a[1]
    u = [v - 1 for v in a[2:2 + 2 * k]]
    g = [[] for _ in range(n)]
    p = 2 + 2 * k
    for i in range(p, len(a), 2):
        v, w = a[i] - 1, a[i + 1] - 1
        g[v].append(w)
        g[w].append(v)
    d = []
    for s in u:
        q = [s]
        z = [-1] * n
        z[s] = 0
        for v in q:
            for w in g[v]:
                if z[w] < 0:
                    z[w] = z[v] + 1
                    q.append(w)
        d.append(z)
    memo = {0: 0}
    def best(mask):
        if mask not in memo:
            i = (mask & -mask).bit_length() - 1
            memo[mask] = max(d[i][u[j]] + best(mask ^ (1 << i) ^ (1 << j)) for j in range(i + 1, 2 * k) if mask & (1 << j))
        return memo[mask]
    out = run(x).split()
    assert len(out) == 1 and out[0].isdigit()
    assert int(out[0]) == best((1 << (2 * k)) - 1)

