def test_exhaustive_small(run, x):
    n, k = map(int, x.split())
    try:
        got = int(run(x).strip())
        parsed = True
    except Exception:
        parsed = False
    assert parsed
    if n <= 5:
        deques = {(1,)}
        for card in range(2, n + 1):
            deques = ({(card,) + d for d in deques} |
                      {d + (card,) for d in deques})
        orders = set()
        def eat(d, order):
            if not d:
                orders.add(order)
                return
            eat(d[1:], order + (d[0],))
            eat(d[:-1], order + (d[-1],))
        for d in deques:
            eat(d, ())
        assert got == sum(order[k - 1] == 1 for order in orders)
    else:
        assert 0 <= got < 1000000007


