def test_exact_enumeration(run, x):
    rows = [list(map(int, line.split())) for line in x.strip().splitlines()]
    n, tiles = rows[0][0], rows[1:]
    s = run(x).strip()
    assert s.isdigit()
    oriented = [[tuple(tile[k:] + tile[:k]) for k in range(4)] for tile in tiles]
    total = 0
    for top in range(n):
        for rt in range(4):
            a, b, c, d = oriented[top][rt]
            for bottom in range(n):
                if bottom == top:
                    continue
                for rb in range(4):
                    e, h, g, f = oriented[bottom][rb]
                    needs = ((a, e, f, b), (b, f, g, c), (c, g, h, d), (d, h, e, a))
                    def fill(pos, used):
                        if pos == 4:
                            return 1
                        ans = 0
                        for tile in range(n):
                            if tile not in used:
                                for face in oriented[tile]:
                                    if face == needs[pos]:
                                        ans += fill(pos + 1, used | {tile})
                        return ans
                    total += fill(0, {top, bottom})
    assert int(s) == total // 24

def test_exact_enumeration_recheck(run, x):
    data = [list(map(int, z.split())) for z in x.strip().splitlines()]
    n = data[0][0]
    faces = [[tuple(r[i:] + r[:i]) for i in range(4)] for r in data[1:]]
    out = run(x).strip()
    assert out.isdigit()
    frames = 0
    for i in range(n):
        for oi in range(4):
            p, q, r, t = faces[i][oi]
            for j in range(n):
                if j == i:
                    continue
                for oj in range(4):
                    u, z, y, v = faces[j][oj]
                    wanted = [(p, u, v, q), (q, v, y, r), (r, y, z, t), (t, z, u, p)]
                    def search(k, used):
                        if k == 4:
                            return 1
                        count = 0
                        for m in range(n):
                            if m in used:
                                continue
                            for om in range(4):
                                if faces[m][om] == wanted[k]:
                                    count += search(k + 1, used | {m})
                        return count
                    frames += search(0, {i, j})
    assert int(out) == frames // 24

