def test_five_halves_small_candidate(run, x):
    out = run(x).strip()
    p, q = map(int, x.split())
    assert out == 'Palindromic tree is better than splay tree' or (out.isdecimal() and int(out) > 0)
    if (p, q) == (5, 2) and out.isdecimal() and int(out) <= 2000:
        n = int(out)
        good = []
        for k in range(1, 2001):
            pal = str(k) == str(k)[::-1]
            prime = k > 1 and all(k % d for d in range(2, int(k ** 0.5) + 1))
            good.append((pal, prime))
        pc = rc = 0
        valid = []
        for k, (pal, prime) in enumerate(good, 1):
            pc += prime
            rc += pal
            if q * pc <= p * rc:
                valid.append(k)
        assert n in valid
        assert not any(k > n for k in valid)

